// Shim HS256 mínimo, compatible con la API de jsonwebtoken para sign()/verify().
import crypto from 'node:crypto';
const b64url = (buf) => Buffer.from(buf).toString('base64url');
function parseExpiresIn(v) {
  if (!v) return null;
  if (typeof v === 'number') return v;
  const m = String(v).match(/^(\d+)([smhd])$/);
  if (!m) return null;
  const mult = { s: 1, m: 60, h: 3600, d: 86400 }[m[2]];
  return Number(m[1]) * mult;
}
export function sign(payload, secret, opts = {}) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const now = Math.floor(Date.now() / 1000);
  const body = { ...payload, iat: now };
  const exp = parseExpiresIn(opts.expiresIn);
  if (exp) body.exp = now + exp;
  const h = b64url(JSON.stringify(header)), p = b64url(JSON.stringify(body));
  const sig = b64url(crypto.createHmac('sha256', secret).update(`${h}.${p}`).digest());
  return `${h}.${p}.${sig}`;
}
export function verify(token, secret) {
  const [h, p, sig] = String(token).split('.');
  if (!h || !p || !sig) throw new Error('jwt malformed');
  const esperado = b64url(crypto.createHmac('sha256', secret).update(`${h}.${p}`).digest());
  if (esperado !== sig) throw new Error('invalid signature');
  const payload = JSON.parse(Buffer.from(p, 'base64url').toString('utf8'));
  if (payload.exp && Math.floor(Date.now() / 1000) > payload.exp) throw new Error('jwt expired');
  return payload;
}
export default { sign, verify };
